export function createSkillCore(root,stages){
root.classList.add('core-summary');root.innerHTML=`<canvas class="core-canvas" aria-hidden="true"></canvas><div class="core-shade"></div><div class="core-title"><p class="eyebrow">THE CONVERGENCE / MY TOOLKIT</p><h2>Everything connects.</h2><p>Explore the skills. Follow the signal.</p></div><div class="core-beacons" role="tablist" aria-label="Explore skill groups">${stages.map((s,i)=>`<button id="core-tab-${i}" role="tab" aria-controls="core-detail" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-core="${i}" style="--x:${i%2?79:21}%;--y:${i<2?31:54}%"><span>0${i+1}</span>${s.short}<i></i></button>`).join('')}</div><div class="core-detail" id="core-detail" role="tabpanel" aria-labelledby="core-tab-0"><p class="core-detail-title"></p><p class="core-tools"></p><a target="_blank" rel="noopener"></a></div><p class="core-instruction">SCROLL TO FOLLOW THE SIGNAL <span>↓</span></p>`;
const q=s=>root.querySelector(s),canvas=q('canvas'),ctx=canvas.getContext('2d'),clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)};let active=0,t=0,paused=false,visible=false,time=0,last=0;
const buttons=[...root.querySelectorAll('[data-core]')];
function select(i){active=i;const s=stages[i];buttons.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});q('.core-detail').setAttribute('aria-labelledby','core-tab-'+i);q('.core-detail-title').textContent=s.name;q('.core-tools').textContent=s.tools.join(' · ');q('.core-detail a').textContent='Applied in '+s.project+' ↗';q('.core-detail a').href='https://github.com/DeV-PrasiddhA/'+s.repo;}
buttons.forEach((b,i)=>{b.onclick=()=>select(i);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;select(n);buttons[n].focus()}}});select(0);
function draw(ms){requestAnimationFrame(draw);const dt=Math.min((ms-last)/1000,.04);last=ms;if(!visible||!ctx||document.hidden)return;if(!paused)time+=dt;const w=canvas.clientWidth,h=canvas.clientHeight,d=Math.min(devicePixelRatio,2);if(!w||!h)return;if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d)}ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);
const enter=ease((t-18.35)/1.05),dive=ease((t-20.9)/1.8),cx=w*.5,cy=h*.425,R=Math.min(w*.23,h*.19),spin=paused?0:time*.15,zoom=1+Math.pow(dive,3)*10;
ctx.save();ctx.translate(cx,cy);ctx.scale(zoom,zoom);ctx.globalCompositeOperation='screen';
const fog=ctx.createRadialGradient(0,0,0,0,0,R*3.2);fog.addColorStop(0,'#d6b36f30');fog.addColorStop(.35,'#3f939026');fog.addColorStop(1,'#07131b00');ctx.fillStyle=fog;ctx.fillRect(-R*3.2,-R*3.2,R*6.4,R*6.4);
// Four interleaved streams spiral from the skill beacons into one shared core.
for(let arm=0;arm<4;arm++){const sx=(arm%2?.29:-.29)*w,sy=(arm<2?.31:.54)*h-cy,color=arm===active?'#f6d797':'#7fcdd0';for(let lane=0;lane<3;lane++){ctx.beginPath();for(let j=0;j<=65;j++){const u=j/65,a=u*5.3+arm*Math.PI/2+spin,r=R*(.2+(1-u)*.9),bend=Math.sin(u*Math.PI);const x=sx*(1-u)+Math.cos(a)*r*bend,y=sy*(1-u)+Math.sin(a)*r*.65*bend;j?ctx.lineTo(x,y+lane*2):ctx.moveTo(x,y+lane*2)}ctx.strokeStyle=arm===active?'#dcb77a38':'#6cb9c521';ctx.lineWidth=lane===1?1.2:.5;ctx.stroke()}
for(let j=0;j<65;j++){const u=paused?j/65:(j/65+time*.085)%1,a=u*5.3+arm*Math.PI/2+spin,r=R*(.2+(1-u)*.9),bend=Math.sin(u*Math.PI),x=(sx*(1-u)+Math.cos(a)*r*bend)*(1.7-.7*enter),y=(sy*(1-u)+Math.sin(a)*r*.65*bend)*(1.7-.7*enter);ctx.globalAlpha=Math.sin(u*Math.PI)*(.35+enter*.65);ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,j%9===0?2:1,0,Math.PI*2);ctx.fill()}}
ctx.globalAlpha=1;
// Rotating tilted meridians form a luminous volume instead of a flat badge.
for(let ring=0;ring<12;ring++){const tilt=ring/12*Math.PI+spin*.7;ctx.beginPath();for(let j=0;j<=100;j++){const a=j/100*Math.PI*2,x=Math.cos(a)*R*.62,y=Math.sin(a)*R*.62*Math.cos(tilt),z=Math.sin(a)*Math.sin(tilt),rot=spin*.4;const xx=x*Math.cos(rot)-y*Math.sin(rot),yy=x*Math.sin(rot)+y*Math.cos(rot);j?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)}ctx.strokeStyle=ring%3?'#8bc9c438':'#edd19999';ctx.lineWidth=ring%3?.65:1.2;ctx.stroke()}
for(let j=0;j<75;j++){const a=j*2.399+spin,r=R*.62*Math.sqrt(1-Math.pow(2*j/75-1,2)),x=Math.cos(a)*r,y=(j/75-.5)*R*1.24;ctx.fillStyle=j%5?'#9dd3cd99':'#ffe9b7';ctx.beginPath();ctx.arc(x,y,1.2,0,Math.PI*2);ctx.fill()}
const flare=ctx.createRadialGradient(0,0,0,0,0,R*.8);flare.addColorStop(0,'#fff0ca');flare.addColorStop(.04,'#ffe5abc9');flare.addColorStop(.2,'#ebbe702a');flare.addColorStop(1,'#edc17e00');ctx.fillStyle=flare;ctx.fillRect(-R,-R,R*2,R*2);
ctx.restore();
}requestAnimationFrame(draw);
return {update(value,stop){t=value;paused=stop;visible=t>18.3&&t<23.2;const exit=ease((t-20.9)/1.2),enter=ease((t-18.35)/.8);root.style.setProperty('--core-copy',String(enter*(1-exit)));q('.core-beacons').inert=exit>.7;q('.core-detail').inert=exit>.7;}};
}
